template<typename Container, typename Index>
decltype(auto) authAndAccess(Container& c, Index i)
{
  // authenticateUser();
  return c[i]; // Return type is exactly the type of c[i]
}

std::vector<int> v = {1, 2, 3};

// authAndAccess returns int&, so we can modify the element
authAndAccess(v, 1) = 20; // v is now {1, 20, 3}

std::vector<bool> boolVec; // operator[] returns a temporary object (value)
auto proxy = authAndAccess(boolVec, 0); // Correctly returns a value type
